"  const refreshCustomerHistory = async (phone) => {
    if (!phone) return;
    try {
      const res = await posService.getCustomerHistory(phone);
      setCustomerHistoryData(res.data || { orders: [], transactions: [] });
    } catch (err) {
      console.error("Failed to refresh customer history:", err);
    }
  };

  const findAssociatedOrder = (tx) => {
    if (!tx || !tx.reason) return null;
    if (!Array.isArray(customerHistoryData?.orders)) return null;
    const reasonLower = tx.reason.toLowerCase();
    for (const order of customerHistoryData.orders) {
      const billNo = String(order.bill_no || '').toLowerCase();
      const orderRef = String(order.order_reference || '').toLowerCase();
      const id = String(order.id || '').toLowerCase();
      if (
        (billNo && reasonLower.includes(billNo)) ||
        (orderRef && reasonLower.includes(orderRef)) ||
        (id && reasonLower.includes(id))
      ) {
        return order;
      }
    }
    return null;
  };"

